-- 1. Dive site types (canonical list)
INSERT INTO dive_site_types (name) VALUES
  ('Beach'),
  ('Cavern/Cave'),
  ('Cenote'),
  ('Geographic Site'),
  ('Lake'),
  ('Other'),
  ('Pier'),
  ('Reef'),
  ('Wreck'),
  ('Wall'),
  ('Reef/Wall'),
  ('Wreck/Reef'),
  ('Drop-off'),
